import os, sys, base64, io, tarfile, glob, shutil

WORK_DIR = '/kaggle/working/cfseg'
os.makedirs(WORK_DIR, exist_ok=True)

# 1. Check if uploaded to /kaggle/input
found_src = False
models_matches = glob.glob('/kaggle/input/**/models.py', recursive=True)
if models_matches:
    src_dir = os.path.dirname(models_matches[0])
    print(f'Found cfseg source code at: {src_dir}')
    for item in os.listdir(src_dir):
        s = os.path.join(src_dir, item)
        d = os.path.join(WORK_DIR, item)
        if os.path.isdir(s):
            shutil.copytree(s, d, dirs_exist_ok=True)
        else:
            shutil.copy2(s, d)
    found_src = True

if not found_src:
    zip_matches = glob.glob('/kaggle/input/**/*.zip', recursive=True)
    import zipfile
    for zf in zip_matches:
        try:
            with zipfile.ZipFile(zf, 'r') as z:
                if 'models.py' in z.namelist() or any(f.endswith('models.py') for f in z.namelist()):
                    print(f'Extracting {zf} into {WORK_DIR}...')
                    z.extractall(WORK_DIR)
                    found_src = True
                    break
        except Exception:
            pass

if not found_src:
    print('Extracting self-contained embedded cfseg codebase...')
    B64_DATA = """"""
    tar_bytes = base64.b64decode(B64_DATA)
    with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode='r:gz') as tar:
        tar.extractall(path=WORK_DIR)
    print('Extraction complete!')

print('Contents of', WORK_DIR, ':', os.listdir(WORK_DIR))
